import{I as t,o as l,c as d,b6 as i,J as o,w as u,j as n,a as s}from"./chunks/framework.BUXTSoD9.js";const g=JSON.parse('{"title":"Double-Diamond-Modell: Erst das Richtige tun, dann die Dinge richtig tun","description":"Ein Einf&uuml;hrungsartikel zum Double-Diamond-Modell f&uuml;r Einsteiger. Verstehen Sie die vier Phasen Discover, Define, Develop und Deliver und vermeiden Sie es, voreilig Prototypen zu erstellen, bevor das Problem klar ist.","frontmatter":{"title":"Double-Diamond-Modell: Erst das Richtige tun, dann die Dinge richtig tun","description":"Ein Einf&uuml;hrungsartikel zum Double-Diamond-Modell f&uuml;r Einsteiger. Verstehen Sie die vier Phasen Discover, Define, Develop und Deliver und vermeiden Sie es, voreilig Prototypen zu erstellen, bevor das Problem klar ist."},"headers":[],"relativePath":"de-de/stage-1/appendix-double-diamond/index.md","filePath":"de-de/stage-1/appendix-double-diamond/index.md"}'),h={name:"de-de/stage-1/appendix-double-diamond/index.md"},b=Object.assign(h,{setup(c){const a="Etwa <strong>1,5 Stunden</strong>";return(m,e)=>{const r=t("ChapterIntroduction");return l(),d("div",null,[e[1]||(e[1]=i('<h1 id="double-diamond-modell-erst-das-richtige-tun-dann-die-dinge-richtig-tun" tabindex="-1">Double-Diamond-Modell: Erst das Richtige tun, dann die Dinge richtig tun <a class="header-anchor" href="#double-diamond-modell-erst-das-richtige-tun-dann-die-dinge-richtig-tun" aria-label="Permalink to “Double-Diamond-Modell: Erst das Richtige tun, dann die Dinge richtig tun”">​</a></h1><p><a id="top-dd"></a></p><h2 id="kapitel-uuml-bersicht" tabindex="-1">Kapitelübersicht <a class="header-anchor" href="#kapitel-uuml-bersicht" aria-label="Permalink to “Kapitel&amp;uuml;bersicht”">​</a></h2>',3)),o(r,{duration:a,tags:["Double Diamond","Design Thinking","Anforderungsanalyse","Lösungsdesign"],coreOutput:"1 klarere Problemdefinition und 1 geeigneterer Validierungsansatz",expectedOutput:"Nicht mehr sofort Prototypen zeichnen, sondern erst das Problem durchdenken und dann Lösungen vergleichen"},{default:u(()=>[...e[0]||(e[0]=[n("p",null,'Viele Menschen, die zum ersten Mal ein Produkt entwickeln, fallen nicht in die Falle "nicht hart genug gearbeitet", sondern in die, zu schnell in die Lösung einzusteigen.',-1),n("p",null,"Sobald eine Richtung im Kopf auftaucht, beginnen sie darüber nachzudenken, wie die Seiten aussehen sollen, wo die Buttons hingehören, ob sie AI integrieren sollten, ob sie eine Login-Registrierung brauchen und welches Tool für den Prototyp geeignet ist. Nach all der Arbeit stellen sie fest, dass die grundlegendste Frage überhaupt nicht geklärt ist: Hat der Nutzer wirklich dieses Problem? Lohnt es sich, dieses Problem jetzt zu lösen? Sie dachten, sie würden das Projekt vorantreiben, aber eigentlich beschleunigen sie nur in die falsche Richtung.",-1),n("p",null,"Das Double-Diamond-Modell wurde genau entwickelt, um diese Situation zu vermeiden.",-1),n("p",null,[s("Seine wertvollste Erinnerung ist: "),n("strong",null,'"Die richtigen Dinge tun" und "die Dinge richtig tun" sind zwei völlig verschiedene Phasen.'),s(" Wenn Sie noch nicht einmal das Problem verstanden haben und schon eilig einen Prototypen erstellen, machen Sie meist nur die falsche Richtung vollständiger.")],-1)])]),_:1}),e[2]||(e[2]=i(`<div class="info custom-block"><p class="custom-block-title">Minimales SOP</p><p><strong>Ziel</strong>: Nach dem Lesen wissen Sie besser, wann Sie zuerst über das Problem nachdenken sollten und wann es an der Zeit ist, Lösungen und Prototypen zu entwerfen. So vermeiden Sie es, von Anfang an sehr fleißig in die falsche Richtung zu arbeiten.</p><p><strong>Aktionspunkte</strong>: Gehen Sie nacheinander die vier Schritte <code>Discover &amp;rarr; Define &amp;rarr; Develop &amp;rarr; Deliver</code> durch und tun Sie in jedem Schritt nur das, was in dieser Phase ansteht.</p><p><strong>Ergebnis</strong>: Sie erhalten eine klarere Problemdefinition, mehrere vergleichbare Lösungen und eine überprüfbare minimale Version.</p><p><strong>Stichwortsprünge</strong>: <a href="#dd-what">Was ist das Double-Diamond-Modell</a> · <a href="#dd-first">Erste Diamant</a> · <a href="#dd-ai">Wie AI Ihnen hilft</a></p></div><h2 id="was-sie-lernen-werden" tabindex="-1">Was Sie lernen werden <a class="header-anchor" href="#was-sie-lernen-werden" aria-label="Permalink to “Was Sie lernen werden”">​</a></h2><ol><li>Was das Double-Diamond-Modell ist und warum es sich für Einsteiger in der Produktentwicklung eignet</li><li>Was die vier Phasen Discover, Define, Develop und Deliver jeweils bewirken</li><li>Wie man unterscheidet: &quot;Soll ich weiter divergieren?&quot; oder &quot;Soll ich jetzt konvergieren?&quot;</li><li>Wie man das Double-Diamond-Modell bei AI-Produkten, Prototyp-Design und Anforderungsvalidierung einsetzt</li></ol><p><a id="dd-what"></a></p><h2 id="_1-was-ist-das-double-diamond-modell-uuml-berhaupt" tabindex="-1"><a href="#top-dd">1. Was ist das Double-Diamond-Modell überhaupt?</a> <a class="header-anchor" href="#_1-was-ist-das-double-diamond-modell-uuml-berhaupt" aria-label="Permalink to “1. Was ist das Double-Diamond-Modell &amp;uuml;berhaupt?”">​</a></h2><p>Das Double-Diamond-Modell ist ein klassischer Designprozess-Rahmen, der vom britischen <strong>Design Council</strong> popularisiert wurde. Es stellt einen vollständigen Design- und Innovationsprozess als zwei aufeinanderfolgende Diamanten dar.</p><p>Warum &quot;Diamanten&quot;? Weil jeder Diamant zwei entgegengesetzte, aber gleichermaßen wichtige Aktionen enthält:</p><ul><li><strong>Divergieren</strong>: Zunächst den Horizont erweitern und mehr Möglichkeiten betrachten</li><li><strong>Konvergieren</strong>: Dann den Bereich verengen, Entscheidungen treffen und Prioritäten setzen</li></ul><p>Der gesamte Prozess besteht aus vier Schritten:</p><ol><li><strong>Discover</strong>: Nutzer, Probleme, Umfeld und Markt umfassend verstehen</li><li><strong>Define</strong>: Aus den vielen Informationen das wirklich löswerte Kernproblem herausfiltern</li><li><strong>Develop</strong>: Mehrere Lösungsansätze um das Kernproblem divergieren</li><li><strong>Deliver</strong>: Auswählen, Prototypen erstellen, testen und die geeignetste Lösung liefern</li></ol><p>Wenn man diese vier Schritte auf einen einprägsamen Satz komprimiert:</p><ul><li><strong>Erster Diamant</strong>: Zunächst klären, welches Problem überhaupt gelöst werden soll</li><li><strong>Zweiter Diamant</strong>: Dann entscheiden, mit welchem Ansatz es gelöst werden soll</li></ul><p>Das lässt sich auch so ausdrücken:</p><ul><li><strong>Erster Diamant: Die richtigen Dinge tun</strong></li><li><strong>Zweiter Diamant: Die Dinge richtig tun</strong></li></ul><h2 id="_2-warum-das-double-diamond-modell-besonders-f-uuml-r-einsteiger-geeignet-ist" tabindex="-1">2. Warum das Double-Diamond-Modell besonders für Einsteiger geeignet ist <a class="header-anchor" href="#_2-warum-das-double-diamond-modell-besonders-f-uuml-r-einsteiger-geeignet-ist" aria-label="Permalink to “2. Warum das Double-Diamond-Modell besonders f&amp;uuml;r Einsteiger geeignet ist”">​</a></h2><p>Der typische Rhythmus von Einsteigern bei der Produktentwicklung sieht oft so aus:</p><ul><li>Eine Idee kommt auf</li><li>Man findet die Richtung toll</li><li>Sofort Prototypen zeichnen</li><li>Beim Erstellen werden es immer mehr Funktionen</li><li>Am Ende weiß man nicht mehr, welches Problem man eigentlich löst</li></ul><p>Der Wert des Double-Diamond-Modells liegt nicht darin, den Prozess komplizierter zu machen, sondern darin, <strong>&quot;das Problem verstehen&quot; und &quot;die Lösung entwerfen&quot; voneinander zu trennen</strong>.</p><p>Das klingt banal, ist aber in der Praxis äußerst wichtig. Denn viele gescheiterte Produkte scheitern nicht an mangelndem Engagement, sondern daran, dass:</p><ul><li>Das falsche Problem gewählt wurde</li><li>Die Nutzer missverstanden wurden</li><li>Zu früh eine Lösung festgelegt wurde</li><li>Viel Zeit in Detailveredelung investiert wurde, ohne die Richtung zu validieren</li></ul><p>Das Double-Diamond-Modell erinnert Sie ständig daran:</p><ul><li>Nicht davon ausgehen, dass das Problem bereits geklärt ist, nur weil die Idee naheliegt</li><li>Nicht davon ausgehen, dass die Lösung es wert ist, umgesetzt zu werden, nur weil sie machbar ist</li><li>Nicht davon ausgehen, dass die Nutzer sie wirklich brauchen, nur weil der Prototyp komplett aussieht</li></ul><p><a id="dd-first"></a></p><h2 id="_3-erster-diamant-die-richtigen-dinge-tun" tabindex="-1"><a href="#top-dd">3. Erster Diamant: Die richtigen Dinge tun</a> <a class="header-anchor" href="#_3-erster-diamant-die-richtigen-dinge-tun" aria-label="Permalink to “3. Erster Diamant: Die richtigen Dinge tun”">​</a></h2><p>Der erste Diamant konzentriert sich auf <strong>das Problem selbst</strong>, nicht auf die Lösung.</p><p>Man kann ihn in einem Satz zusammenfassen: <strong>Nicht sofort loslegen, sondern zuerst klären, ob es sich überhaupt lohnt.</strong></p><h3 id="_3-1-discover-zun-auml-chst-den-problemraum-ouml-ffnen" tabindex="-1">3.1 Discover: Zunächst den Problemraum öffnen <a class="header-anchor" href="#_3-1-discover-zun-auml-chst-den-problemraum-ouml-ffnen" aria-label="Permalink to “3.1 Discover: Zun&amp;auml;chst den Problemraum &amp;ouml;ffnen”">​</a></h3><p>Die Kernaufgabe der Discover-Phase ist <strong>umfassende Recherche, keine schnellen Schlüsse</strong>.</p><p>Typische Tätigkeiten in diesem Schritt:</p><ul><li>Beobachten, wie Nutzer in echten Szenarien agieren</li><li>Potenzielle Nutzer interviewen und herausfinden, wann sie zuletzt ein Problem hatten</li><li>Beobachten, wie sie sich aktuell behelfen</li><li>Wettbewerbs- und Alternativlösungen analysieren</li><li>Markt-, Prozess-, Restriktions- und Wertschöpfungsinformationen sammeln</li></ul><p>Viele glauben, Discover bedeute einfach &quot;mehr Material lesen&quot;. Wichtiger ist jedoch: <strong>Sie müssen Menschen und Szenarien verstehen, nicht nur Informationen sammeln.</strong></p><p>Wenn Sie beispielsweise ein Tool entwickeln möchten, das &quot;AI beim Erstellen von Meeting-Protokollen hilft&quot;, sollten Sie in der Discover-Phase vor allem Folgendes klären:</p><ul><li>Was Nutzer nach Meetings am meisten belastet</li><li>Ist das Aufzeichnen das Problem, das Zusammenfassen oder das Weiterleiten</li><li>Schreiben sie selbst, lassen sie Praktikanten schreiben, hören sie Aufnahmen ab oder verzichten sie ganz auf Protokolle</li><li>Welche Meeting-Szenarien Protokolle am meisten benötigen und welche überhaupt nicht</li></ul><p>Das wichtigste Ziel dieses Schritts ist nicht, eine Antwort zu finden, sondern <strong>nicht zu früh zu glauben, man hätte bereits die Antwort.</strong></p><h3 id="_3-2-define-aus-den-informationen-das-kernproblem-destillieren" tabindex="-1">3.2 Define: Aus den Informationen das Kernproblem destillieren <a class="header-anchor" href="#_3-2-define-aus-den-informationen-das-kernproblem-destillieren" aria-label="Permalink to “3.2 Define: Aus den Informationen das Kernproblem destillieren”">​</a></h3><p>Wenn Discover das Öffnen des Horizonts ist, ist Define das Einengen.</p><p>In der Define-Phase geht es nicht darum, alle Beobachtungen zu behalten, sondern zu fragen:</p><ul><li>Welches Problem ist wirklich am wichtigsten und sollte zuerst gelöst werden</li><li>Welches Problem am häufigsten auftritt, am schmerzhaftesten ist und den größten Wert bietet</li><li>Auf welches Szenario wir uns in der ersten Version konzentrieren sollten</li></ul><p>Der Kern dieses Schritts besteht darin, ein breites Thema auf eine klare Problemdefinition zu verdichten.</p><p>Vielleicht sagen Sie zunächst:</p><blockquote><p>Ich möchte ein AI-Tool entwickeln, das die Meeting-Effizienz steigert.</p></blockquote><p>In der Define-Phase könnte eine bessere Formulierung lauten:</p><blockquote><p>Wir lösen zunächst das Problem, dass Projektteams nach 30 bis 60 Minuten dauernden Kooperationsmeetings nicht in der Lage sind, innerhalb von 10 Minuten ein Protokoll mit Aufgaben, Verantwortlichen und Fristen zu erstellen.</p></blockquote><p>Jetzt wird das Problem konkreter:</p><ul><li>Wer sind die Nutzer</li><li>Was ist das Szenario</li><li>Wo liegt der Engpass</li><li>Was ist das Erfolgskriterium</li></ul><p>Das Wesen von Define ist: <strong>Von &quot;es gibt viele Probleme&quot; konvergieren zu &quot;welches Problem lösen wir diesmal zuerst&quot;.</strong></p><h2 id="_4-zweiter-diamant-die-dinge-richtig-tun" tabindex="-1">4. Zweiter Diamant: Die Dinge richtig tun <a class="header-anchor" href="#_4-zweiter-diamant-die-dinge-richtig-tun" aria-label="Permalink to “4. Zweiter Diamant: Die Dinge richtig tun”">​</a></h2><p>Erst wenn der erste Diamant abgeschlossen ist, sollten Sie in den zweiten Diamanten eintreten. Denn jetzt lösen Sie keine vage Richtung mehr, sondern ein konkretes, bereits eingegrenztes Problem.</p><h3 id="_4-1-develop-l-ouml-sungsans-auml-tze-um-das-kernproblem-divergieren" tabindex="-1">4.1 Develop: Lösungsansätze um das Kernproblem divergieren <a class="header-anchor" href="#_4-1-develop-l-ouml-sungsans-auml-tze-um-das-kernproblem-divergieren" aria-label="Permalink to “4.1 Develop: L&amp;ouml;sungsans&amp;auml;tze um das Kernproblem divergieren”">​</a></h3><p>Der Fokus der Develop-Phase liegt auf <strong>der Exploration mehrerer möglicher Lösungen für dasselbe Problem</strong>.</p><p>Beachten Sie: Diese Divergenz unterscheidet sich von der Discover-Phase.</p><ul><li>Die Divergenz in Discover erforscht den Problemraum</li><li>Die Divergenz in Develop erforscht den Lösungsraum</li></ul><p>Beim Meeting-Protokoll-Beispiel könnten Sie in der Develop-Phase Folgendes in Betracht ziehen:</p><ul><li>Web-Tool oder Meeting-Plugin</li><li>Hochgeladene Audioaufzeichnung nachträglich verarbeiten oder Echtzeit-Mitschrift</li><li>Nur Zusammenfassung oder Fokus auf Aufgabenextraktion</li><li>Persönliche Effizienz oder Team-Synchronisation betonen</li><li>Freie Bearbeitung für Nutzer oder direkte strukturierte Vorlage ausgeben</li></ul><p>Dieser Schritt eignet sich gut für Brainstorming und die Zusammenarbeit im Team.</p><p>Aber es gibt eine Voraussetzung: <strong>Alle Lösungen müssen demselben definierten Problem dienen.</strong> Wenn das Problem nicht klar definiert ist, wird Develop schnell wieder zu einem ungeordneten Sammelsurium von Funktionen.</p><h3 id="_4-2-deliver-l-ouml-sung-ausw-auml-hlen-prototyp-erstellen-testen-und-liefern" tabindex="-1">4.2 Deliver: Lösung auswählen, Prototyp erstellen, testen und liefern <a class="header-anchor" href="#_4-2-deliver-l-ouml-sung-ausw-auml-hlen-prototyp-erstellen-testen-und-liefern" aria-label="Permalink to “4.2 Deliver: L&amp;ouml;sung ausw&amp;auml;hlen, Prototyp erstellen, testen und liefern”">​</a></h3><p>Deliver ist die Konvergenzphase im zweiten Diamanten.</p><p>Jetzt geht es nicht mehr darum, weiter nachzudenken, sondern zu entscheiden:</p><ul><li>Welcher Ansatz passt am besten zur aktuellen Phase</li><li>Welche Version am kleinsten, aber am nützlichsten ist</li><li>Welche Funktionen zuerst entwickelt werden müssen und welche später kommen können</li><li>Wie man Prototypen erstellt, testet und in kleinem Rahmen validiert</li></ul><p>Viele glauben, Deliver bedeute einfach &quot;launch&quot;. Genauer gesagt bedeutet es: <strong>Eine Lösung in etwas Überprüfbares, Validierbares und Iterierbares verwandeln.</strong></p><p>Das kann sein:</p><ul><li>Ein Low-Fidelity-Flussdiagramm</li><li>Ein Figma-Prototyp</li><li>Ein lauffähiger MVP</li><li>Ein kleiner Nutzer-Test</li><li>Eine iterative Version nach echtem Feedback</li></ul><p>Der Fokus von Deliver liegt nicht auf &quot;perfekter Auslieferung&quot;, sondern darauf, <strong>die Lösung so schnell wie möglich in einer realen Umgebung zu validieren.</strong></p><h2 id="_5-eine-einpr-auml-gsame-uuml-bersichtstabelle" tabindex="-1">5. Eine einprägsame Übersichtstabelle <a class="header-anchor" href="#_5-eine-einpr-auml-gsame-uuml-bersichtstabelle" aria-label="Permalink to “5. Eine einpr&amp;auml;gsame &amp;Uuml;bersichtstabelle”">​</a></h2><p>Wenn Sie die vier Phasen immer wieder durcheinanderbringen, merken Sie sich einfach diese Version:</p><table tabindex="0"><thead><tr><th>Phase</th><th>Was Sie tun</th><th>Schlüsselwörter</th><th>Typische Ergebnisse</th></tr></thead><tbody><tr><td>Discover</td><td>Problem verstehen</td><td>Recherche, Beobachtung, Interviews, Informationssammlung</td><td>Nutzererkenntnisse, Szenarienotizen, Problemliste</td></tr><tr><td>Define</td><td>Problem definieren</td><td>Destillieren, Fokussieren, Priorisieren, Problem umformulieren</td><td>Problemdefinition, Prioritäten, MVP-Ansatz</td></tr><tr><td>Develop</td><td>Lösungen erkunden</td><td>Brainstorming, Vergleichen, Co-Kreation, Prototyp-Ideen</td><td>Lösungsliste, Flussskizzen, Prototyp-Richtung</td></tr><tr><td>Deliver</td><td>Lösung validieren</td><td>Prototyp, Testen, Iterieren, Ausliefern</td><td>Prototyp, Test-Feedback, optimierte Version</td></tr></tbody></table><p>Noch kompakter:</p><ul><li><strong>Discover / Define</strong>: &quot;Die richtigen Dinge tun&quot;</li><li><strong>Develop / Deliver</strong>: &quot;Die Dinge richtig tun&quot;</li></ul><h2 id="_6-die-h-auml-ufigsten-missverst-auml-ndnisse-zum-double-diamond-modell" tabindex="-1">6. Die häufigsten Missverständnisse zum Double-Diamond-Modell <a class="header-anchor" href="#_6-die-h-auml-ufigsten-missverst-auml-ndnisse-zum-double-diamond-modell" aria-label="Permalink to “6. Die h&amp;auml;ufigsten Missverst&amp;auml;ndnisse zum Double-Diamond-Modell”">​</a></h2><h3 id="_6-1-direkt-zu-deliver-springen-ohne-discover" tabindex="-1">6.1 Direkt zu Deliver springen, ohne Discover <a class="header-anchor" href="#_6-1-direkt-zu-deliver-springen-ohne-discover" aria-label="Permalink to “6.1 Direkt zu Deliver springen, ohne Discover”">​</a></h3><p>Das ist der häufigste Fehler. Viele beginnen sofort mit dem Zeichnen von Prototypen, dem Schreiben von PRDs, dem Anbinden von Modellen und dem Erstellen von Seiten, sobald sie eine Idee haben.</p><p>Das Problem ist nicht, dass Sie nicht fleißig genug arbeiten, sondern dass Sie möglicherweise nicht einmal bestätigt haben, ob sich das Problem überhaupt zu lösen lohnt.</p><h3 id="_6-2-lange-discover-phase-aber-nie-define" tabindex="-1">6.2 Lange Discover-Phase, aber nie Define <a class="header-anchor" href="#_6-2-lange-discover-phase-aber-nie-define" aria-label="Permalink to “6.2 Lange Discover-Phase, aber nie Define”">​</a></h3><p>Ein anderer Extremfall: ständig recherchieren, Material lesen, Interviews führen, aber sich nicht trauen zu konvergieren.</p><p>Das Double-Diamond-Modell soll Sie nicht endlos divergieren lassen, sondern erinnert Sie: Nach der Divergenz müssen Sie in die Entscheidungs- und Priorisierungsphase übergehen.</p><h3 id="_6-3-nach-define-das-problem-heimlich-auml-ndern" tabindex="-1">6.3 Nach Define das Problem heimlich ändern <a class="header-anchor" href="#_6-3-nach-define-das-problem-heimlich-auml-ndern" aria-label="Permalink to “6.3 Nach Define das Problem heimlich &amp;auml;ndern”">​</a></h3><p>Viele Teams ändern in der Develop-Phase die Problemdefinition, weil ein bestimmter Ansatz einfacher umsetzbar ist.</p><p>Das ist gefährlich. Denn Sie lösen möglicherweise gar kein Problem, sondern suchen nur Rechtfertigungen für Ihren bevorzugten Ansatz.</p><h3 id="_6-4-deliver-als-kompletter-launch-missverstehen" tabindex="-1">6.4 Deliver als &quot;kompletter Launch&quot; missverstehen <a class="header-anchor" href="#_6-4-deliver-als-kompletter-launch-missverstehen" aria-label="Permalink to “6.4 Deliver als &quot;kompletter Launch&quot; missverstehen”">​</a></h3><p>Deliver bedeutet nicht, dass das fertige Produkt komplett sein muss. Oft ist ein testbarer Prototyp oder eine kleine Nutzererprobung bereits ein gutes Deliverable.</p><h2 id="_7-wie-das-double-diamond-modell-bei-ai-produkten-eingesetzt-wird" tabindex="-1">7. Wie das Double-Diamond-Modell bei AI-Produkten eingesetzt wird <a class="header-anchor" href="#_7-wie-das-double-diamond-modell-bei-ai-produkten-eingesetzt-wird" aria-label="Permalink to “7. Wie das Double-Diamond-Modell bei AI-Produkten eingesetzt wird”">​</a></h2><p>AI-Produkte neigen besonders zur &quot;Fähigkeiten zuerst&quot;-Falle, weil die Modellfähigkeiten so verlockend aussehen. Man möchte direkt darüber nachdenken:</p><ul><li>Soll ich multimodal integrieren</li><li>Soll ich einen Agenten erstellen</li><li>Soll ich einen Workflow hinzufügen</li><li>Soll ich Sprache, Bilder oder Websuche anbinden</li></ul><p>Das Double-Diamond-Modell zwingt Sie jedoch, zuerst zu fragen:</p><ul><li>Wo genau hängen die Nutzer fest</li><li>Muss dieses Problem zwingend mit AI gelöst werden</li><li>Wenn man keine AI verwendet, was genau ist am aktuellen Ansatz am schlechtesten</li><li>Wenn AI hinzugefügt wird, was ist der zentrale Fortschritt</li></ul><p>Das hilft Ihnen, eine häufige Situation zu vermeiden: <strong>Starke Fähigkeiten, schwacher Wert.</strong></p><p>Ein praktischer Ablauf:</p><ol><li>In der Discover-Phase beobachten, wie Nutzer Aufgaben aktuell erledigen</li><li>In der Define-Phase das schmerzhafteste Szenario als klare Problemdefinition formulieren</li><li>In der Develop-Phase vergleichen, welche AI-Fähigkeiten am besten zu diesem Problem passen</li><li>In der Deliver-Phase eine Minimalversion erstellen und von echten Nutzern testen lassen</li></ol><h2 id="_8-eine-direkt-anwendbare-double-diamond-vorlage" tabindex="-1">8. Eine direkt anwendbare Double-Diamond-Vorlage <a class="header-anchor" href="#_8-eine-direkt-anwendbare-double-diamond-vorlage" aria-label="Permalink to “8. Eine direkt anwendbare Double-Diamond-Vorlage”">​</a></h2><p>Wenn Sie an Ihrem eigenen Produkt arbeiten, können Sie in dieser Reihenfolge vorgehen:</p><h3 id="discover" tabindex="-1">Discover <a class="header-anchor" href="#discover" aria-label="Permalink to “Discover”">​</a></h3><ul><li>Wer sind die Nutzer, die ich beobachte?</li><li>Wann hatten sie zuletzt dieses Problem?</li><li>Wie lösen sie es derzeit?</li><li>Was sie am meisten nervt, am langsamsten ist und sie am wenigsten beruhigt?</li></ul><h3 id="define" tabindex="-1">Define <a class="header-anchor" href="#define" aria-label="Permalink to “Define”">​</a></h3><ul><li>Welches dieser Probleme ist am wertvollsten und sollte zuerst gelöst werden?</li><li>Welches Szenario ist am häufigsten oder am kritischsten?</li><li>Wen und was bedienen wir in der ersten Version ausschließlich?</li><li>Wie ändert sich der Nutzerstatus, wenn das Problem erfolgreich gelöst ist?</li></ul><h3 id="develop" tabindex="-1">Develop <a class="header-anchor" href="#develop" aria-label="Permalink to “Develop”">​</a></h3><ul><li>Welche möglichen Lösungen gibt es für dieses Problem?</li><li>Welche Lösungen sind am leichtesten, am schnellsten und am einfachsten zu validieren?</li><li>Was muss zwingend gemacht werden, was kann später erfolgen?</li></ul><h3 id="deliver" tabindex="-1">Deliver <a class="header-anchor" href="#deliver" aria-label="Permalink to “Deliver”">​</a></h3><ul><li>Was ist das Minimalste, das wir liefern können, um diese Richtung zu validieren?</li><li>Ist es ein Flussdiagramm, ein Prototyp oder ein MVP?</li><li>Wen müssen wir zum Testen einladen?</li><li>Wie entscheiden wir nach dem Test, ob wir weitermachen, ändern oder abbrechen?</li></ul><h2 id="_9-ein-beispiel-das-auch-einsteiger-verstehen" tabindex="-1">9. Ein Beispiel, das auch Einsteiger verstehen <a class="header-anchor" href="#_9-ein-beispiel-das-auch-einsteiger-verstehen" aria-label="Permalink to “9. Ein Beispiel, das auch Einsteiger verstehen”">​</a></h2><p>Angenommen, Sie möchten ein AI-Tool entwickeln, &quot;das Hochschulabsolventen bei der Vorbereitung von Lebensläufen für Bewerbungen hilft&quot;.</p><p>Viele würden sofort in den zweiten Diamanten springen und über Folgendes nachdenken:</p><ul><li>Ein-Klick-Verschönerung</li><li>Intelligentes Umschreiben</li><li>Automatisches JD-Matching</li><li>Generierung von Selbstvorstellungen</li></ul><p>Nach dem Double-Diamond-Modell wäre ein besserer Prozess:</p><h3 id="erster-diamant" tabindex="-1">Erster Diamant <a class="header-anchor" href="#erster-diamant" aria-label="Permalink to “Erster Diamant”">​</a></h3><p><strong>Discover</strong></p><ul><li>Mit frischen Absolventen darüber sprechen, wann sie zuletzt einen Lebenslauf geändert haben</li><li>Beobachten, wie sie ihren alten Lebenslauf in eine neue Version umwandeln</li><li>Verstehen, ob sie am meisten von &quot;nicht wissen, was sie schreiben sollen&quot;, &quot;nicht wissen, wie sie ändern sollen&quot; oder &quot;nicht beurteilen können, ob es gut genug ist&quot; betroffen sind</li></ul><p><strong>Define</strong></p><ul><li>Zu einer spezifischeren Problemdefinition konvergieren:</li><li>Nicht &quot;Studierende können keine Lebensläufe erstellen&quot;</li><li>Sondern &quot;Studierende bei der ersten Bewerbung um ein Praktikum können ihre bisherigen Erfahrungen nicht in Formulierungen umwandeln, die zur Stellenbeschreibung passen, und verzögern deshalb ihre Bewerbung&quot;</li></ul><h3 id="zweiter-diamant" tabindex="-1">Zweiter Diamant <a class="header-anchor" href="#zweiter-diamant" aria-label="Permalink to “Zweiter Diamant”">​</a></h3><p><strong>Develop</strong></p><ul><li>Mehrere Lösungsansätze erwägen: Vorlagenbibliothek, AI-Umschreibung, Stellenvergleich, Lebenslauf-Bewertung, Fallbeispiele</li></ul><p><strong>Deliver</strong></p><ul><li>Erste Version nur: &quot;Erfahrungs-Bullet-Points basierend auf der Stellenbeschreibung umschreiben&quot;</li><li>5 Studierenden zum Test geben und prüfen, ob sie schneller die erste Version ihres Lebenslaufs einreichen</li></ul><p>Sie werden feststellen: Wenn der erste Diamant gründlich bearbeitet wurde, wird der zweite viel klarer.</p><h2 id="_10-zusammenfassung" tabindex="-1">10. Zusammenfassung <a class="header-anchor" href="#_10-zusammenfassung" aria-label="Permalink to “10. Zusammenfassung”">​</a></h2><p>Die größte Stärke des Double-Diamond-Modells liegt darin, ein Chaos in vier klarere Aktionen zu zerlegen:</p><ul><li>Erst divergieren, um das Problem zu verstehen</li><li>Dann konvergieren, um das Problem zu definieren</li><li>Dann divergieren, um Lösungen zu erkunden</li><li>Schließlich konvergieren, um die Lösung zu liefern</li></ul><p>Es macht Sie nicht langsamer, sondern hilft Ihnen, <strong>viele Umwege zu vermeiden, die beschäftigt aussehen, aber in die falsche Richtung führen.</strong></p><p>Besonders in der AI-Ära, in der das Erstellen von Dingen immer schneller wird, ist das Double-Diamond-Modell sogar noch wichtiger. Denn wenn &quot;etwas zu bauen&quot; immer einfacher wird, wird die wirklich seltene Fähigkeit: <strong>Lösen Sie ein Problem, das es wert ist, gelöst zu werden, und tun Sie es auf angemessene Weise.</strong></p><p>Merken Sie sich nur diesen einen Satz:</p><p><strong>Erst die richtigen Dinge tun, dann die Dinge richtig tun.</strong></p><p><a id="dd-ai"></a></p><h2 id="_11-wie-sie-ai-nutzen-k-ouml-nnen-um-den-double-diamond-prozess-zu-durchlaufen" tabindex="-1"><a href="#top-dd">11. Wie Sie AI nutzen können, um den Double-Diamond-Prozess zu durchlaufen</a> <a class="header-anchor" href="#_11-wie-sie-ai-nutzen-k-ouml-nnen-um-den-double-diamond-prozess-zu-durchlaufen" aria-label="Permalink to “11. Wie Sie AI nutzen k&amp;ouml;nnen, um den Double-Diamond-Prozess zu durchlaufen”">​</a></h2><p>Das Double-Diamond-Modell ist kein AI-Tool, aber AI eignet sich hervorragend als &quot;Beschleuniger&quot; in den vier Phasen. Der Schlüssel liegt nicht darin, AI für Sie entscheiden zu lassen, sondern darin, sie zu nutzen, um Ihren Horizont zu erweitern, Informationen zu ordnen, Lösungen zu vergleichen und Validierungsmaterial zu erstellen.</p><h3 id="_11-1-in-der-discover-phase-ai-f-uuml-r-eine-erste-informationsgrundlage-nutzen" tabindex="-1">11.1 In der Discover-Phase: AI für eine erste Informationsgrundlage nutzen <a class="header-anchor" href="#_11-1-in-der-discover-phase-ai-f-uuml-r-eine-erste-informationsgrundlage-nutzen" aria-label="Permalink to “11.1 In der Discover-Phase: AI f&amp;uuml;r eine erste Informationsgrundlage nutzen”">​</a></h3><p>Vor offiziellen Interviews und Recherche können Sie AI zunächst einen leichten Problemaufklärungsscan durchführen lassen:</p><ul><li>Welche gängigen Alternativlösungen gibt es auf dem Markt</li><li>Worauf Nutzer in öffentlichen Communitys am häufigsten klagen</li><li>In welchen Szenarien und bei welchen Zielgruppen dieses Problem auftritt</li><li>Was bestehende Produkte übersehen</li></ul><p>Dieser Schritt kann echte Recherche nicht ersetzen, eignet sich aber gut, um schnell eine Problem-Landkarte zu erstellen.</p><p>Ein einfacher Einsteiger-Prompt könnte lauten:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ich m&amp;ouml;chte ein Tool entwickeln, das Studierenden beim Umschreiben von Lebensl&amp;auml;ufen hilft.</span></span>
<span class="line"><span>Bitte schlage nicht sofort Funktionen vor, sondern zeige zuerst, welche Schwierigkeiten in diesem Problem am h&amp;auml;ufigsten auftreten.</span></span></code></pre></div><p>AI könnte ausgeben:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Erste Problem-Landkarte:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Man wei&amp;szlig; nicht, welche Erfahrungen man erw&amp;auml;hnen sollte</span></span>
<span class="line"><span>2. Man wei&amp;szlig; nicht, wie man den Lebenslauf auf eine bestimmte Stelle anpasst</span></span>
<span class="line"><span>3. Nach vielen &amp;Uuml;berarbeitungen ist man sich immer noch nicht sicher, ob es gut genug ist</span></span>
<span class="line"><span>4. Man braucht jemanden zum Gegenlesen, m&amp;ouml;chte aber nicht st&amp;auml;ndig um Gef&amp;auml;lligkeiten bitten</span></span>
<span class="line"><span>5. Wegen der Unsicherheit verschobt man den Lebenslauf immer wieder</span></span></code></pre></div><p>Diese Ausgabe soll Ihnen nicht die Entscheidung abnehmen, sondern Ihnen den schnelleren Einstieg in Discover ermöglichen.</p><h3 id="_11-2-in-der-define-phase-ai-beim-konvergieren-der-problemdefinition-unterst-uuml-tzen" tabindex="-1">11.2 In der Define-Phase: AI beim Konvergieren der Problemdefinition unterstützen <a class="header-anchor" href="#_11-2-in-der-define-phase-ai-beim-konvergieren-der-problemdefinition-unterst-uuml-tzen" aria-label="Permalink to “11.2 In der Define-Phase: AI beim Konvergieren der Problemdefinition unterst&amp;uuml;tzen”">​</a></h3><p>Nachdem man viele Informationen gesammelt hat, ist das Schwierigste oft, das Problem in einen wirklich klaren Satz zu verdichten. Sie können Ihre Recherche-Notizen an AI übergeben und sie bitten, daraus mehrere Problemdefinitionen zu komprimieren:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Hier sind die Nutzer-Feedbacks und Recherche-Notizen, die ich in der Discover-Phase gesammelt habe:</span></span>
<span class="line"><span>[Inhalt einf&amp;uuml;gen]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Bitte hilf mir bei drei Dingen:</span></span>
<span class="line"><span>1. Die h&amp;auml;ufigsten Problemmuster zusammenfassen</span></span>
<span class="line"><span>2. Nach H&amp;auml;ufigkeit, Schmerzintensit&amp;auml;t und Validierbarkeit 3 priorisierte Probleme identifizieren</span></span>
<span class="line"><span>3. Jedes Problem als konkrete Problemdefinition formulieren</span></span></code></pre></div><p>So kommen Sie leichter in die Define-Phase, anstatt im Zustand &quot;es gibt so viele Probleme&quot; stecken zu bleiben.</p><p>Sie können die Eingabe auch sehr einfach formulieren:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Die Probleme, die ich bisher gesammelt habe:</span></span>
<span class="line"><span>1. Man wei&amp;szlig; nicht, was man im Lebenslauf schreiben soll</span></span>
<span class="line"><span>2. Man wei&amp;szlig; nicht, wie man ihn anpasst</span></span>
<span class="line"><span>3. Man hat nie das Gef&amp;uuml;hl, er sei gut genug, und traut sich nicht, ihn abzuschicken</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Bitte sage mir, welches Problem sich am besten f&amp;uuml;r die erste Version eignet.</span></span></code></pre></div><p>AI könnte ausgeben:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Empfohlenes Priorit&amp;auml;tsproblem:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;Studierende bei ihrer ersten Praktikumsbewerbung sind sich nicht sicher, ob ihr Lebenslauf bereit zum Abschicken ist, &amp;uuml;berarbeiten ihn endlos und verschoben die Bewerbung.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Gr&amp;uuml;nde:</span></span>
<span class="line"><span>1. Dieses Problem ist konkreter</span></span>
<span class="line"><span>2. Es erkl&amp;auml;rt das Verschleppungsverhalten</span></span>
<span class="line"><span>3. Es ist einfacher, eine kleine Version zur Validierung zu entwerfen</span></span></code></pre></div><p>Diese Art von Ausgabe ist sehr nützlich, denn sie hilft, aus einer Vielzahl vager Probleme eine Definition herauszudestillieren, die als MVP-Startpunkt dienen kann.</p><h3 id="_11-3-in-der-develop-phase-ai-nutzen-um-mehrere-l-ouml-sungen-zu-divergieren" tabindex="-1">11.3 In der Develop-Phase: AI nutzen, um mehrere Lösungen zu divergieren <a class="header-anchor" href="#_11-3-in-der-develop-phase-ai-nutzen-um-mehrere-l-ouml-sungen-zu-divergieren" aria-label="Permalink to “11.3 In der Develop-Phase: AI nutzen, um mehrere L&amp;ouml;sungen zu divergieren”">​</a></h3><p>Viele verharren nach der Problemdefinition auf dem ersten Lösungsansatz, der ihnen in den Sinn kommt. AI eignet sich hervorragend dafür, Sie zur Divergenz zu zwingen:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ich habe ein Kernproblem definiert: [Ihre Problemdefinition]</span></span>
<span class="line"><span>Bitte gib mir nicht sofort eine Endl&amp;ouml;sung, sondern schlage aus folgenden Perspektiven jeweils 2-3 L&amp;ouml;sungsrichtungen vor:</span></span>
<span class="line"><span>1. Das leichtgewichtigste MVP</span></span>
<span class="line"><span>2. Der am besten zur Bedarfsvalidierung geeignete Ansatz</span></span>
<span class="line"><span>3. Der erfahrungssteigernde Ansatz</span></span>
<span class="line"><span>4. Ein Ansatz ohne AI</span></span>
<span class="line"><span>5. Ein Ansatz mit AI</span></span>
<span class="line"><span>Vergleiche schlie&amp;szlig;lich die Vorteile, Risiken und Validierungskosten jedes Ansatzes.</span></span></code></pre></div><p>So werden Sie nicht zu früh auf einen einzigen Ansatz festgelegt.</p><p>Ein einfacher Prompt könnte lauten:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Meine aktuelle Problemdefinition lautet:</span></span>
<span class="line"><span>&quot;Studierende sind sich nicht sicher, ob ihr Lebenslauf abschickbereit ist, und verschoben ihn deshalb st&amp;auml;ndig.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Bitte schlage mir 4 verschiedene L&amp;ouml;sungsans&amp;auml;tze vor, nicht nur einen.</span></span></code></pre></div><p>AI könnte ausgeben:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ansatz 1: Checkliste f&amp;uuml;r abschickbereite Lebensl&amp;auml;ufe</span></span>
<span class="line"><span>Ansatz 2: Gezieltes Umschreiben basierend auf der Stellenbeschreibung</span></span>
<span class="line"><span>Ansatz 3: Lebenslauf hochladen und Risikohinweise erhalten</span></span>
<span class="line"><span>Ansatz 4: Hervorragende Beispiele zum Vergleich zeigen</span></span></code></pre></div><p>Jetzt können Sie leichter &quot;Lösungen vergleichen&quot;, anstatt von Anfang an nur auf AI-Umschreibung zu starren.</p><h3 id="_11-4-in-der-deliver-phase-ai-beim-generieren-von-prototyp-text-und-testmaterial-unterst-uuml-tzen" tabindex="-1">11.4 In der Deliver-Phase: AI beim Generieren von Prototyp-Text und Testmaterial unterstützen <a class="header-anchor" href="#_11-4-in-der-deliver-phase-ai-beim-generieren-von-prototyp-text-und-testmaterial-unterst-uuml-tzen" aria-label="Permalink to “11.4 In der Deliver-Phase: AI beim Generieren von Prototyp-Text und Testmaterial unterst&amp;uuml;tzen”">​</a></h3><p>Wenn Sie in die Deliver-Phase eintreten, ist AI hervorragend dafür geeignet, folgende Aufgaben zu beschleunigen:</p><ul><li>Seitentexte für Low-Fidelity-Prototypen generieren</li><li>Nutzer-Testskripte erstellen</li><li>Mehrere vergleichbare Versionen von &amp;Uberschriften, Buttons und Beschreibungen erstellen</li><li>Feedback und Problemlisten nach Tests zusammenfassen</li></ul><p>Beispielsweise könnten Sie AI bitten, ein 20-minütiges Nutzer-Testskript zu erstellen oder 5 Nutzer-Feedbacks in &quot;weitermachen / Richtung ändern / pausieren&quot; zu kategorisieren.</p><p>Ein minimaler Prompt könnte lauten:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ich habe einen einfachen Prototyp erstellt:</span></span>
<span class="line"><span>Der Nutzer l&amp;auml;dt einen Lebenslauf hoch und das System zeigt an, welche Stellen noch nicht bewerbungstauglich sind.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Bitte generiere ein 15-min&amp;uuml;tiges Nutzer-Testskript.</span></span></code></pre></div><p>AI könnte ausgeben:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>15-min&amp;uuml;tiges Testskript:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Bitte den Nutzer zun&amp;auml;chst, seine letzte Lebenslauferfahrung zu beschreiben</span></span>
<span class="line"><span>2. Den Nutzer den Lebenslauf selbstst&amp;auml;ndig hochladen lassen</span></span>
<span class="line"><span>3. Beobachten, ob er die Feedback-Ergebnisse versteht</span></span>
<span class="line"><span>4. Fragen: Welche Hinweise waren am hilfreichsten, welche verwirrend</span></span>
<span class="line"><span>5. Fragen: W&amp;uuml;rden Sie das Tool vor der n&amp;auml;chsten Bewerbung erneut nutzen</span></span></code></pre></div><p>Diese Art von Ausgabe ist sehr praktisch, denn sie hilft, von &quot;Ich habe den Prototyp fertig&quot; zu &quot;Wie teste ich als Nächstes&quot; zu gelangen.</p><h3 id="_11-5-ai-als-phasen-w-auml-chter-einsetzen" tabindex="-1">11.5 AI als &quot;Phasen-Wächter&quot; einsetzen <a class="header-anchor" href="#_11-5-ai-als-phasen-w-auml-chter-einsetzen" aria-label="Permalink to “11.5 AI als &quot;Phasen-W&amp;auml;chter&quot; einsetzen”">​</a></h3><p>Das häufigste Problem beim Double-Diamond-Modell ist, dass Menschen Phasen überspringen. Sie können AI direkt als Wächter fungieren lassen, der Sie erinnert, wo Sie sich gerade befinden:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Bitte spiele die Rolle eines Produktprozess-Coachs.</span></span>
<span class="line"><span>Hier ist mein aktueller Projektstatus: [Ihre Beschreibung]</span></span>
<span class="line"><span>Bitte beurteile, ob ich mich eher in Discover, Define, Develop oder Deliver befinde.</span></span>
<span class="line"><span>Und sage mir:</span></span>
<span class="line"><span>1. Ob ich zu fr&amp;uuml;h in die n&amp;auml;chste Phase gesprungen bin</span></span>
<span class="line"><span>2. Welche Aktion in der aktuellen Phase am wichtigsten nachzuholen ist</span></span>
<span class="line"><span>3. Welche Dinge ich jetzt noch nicht tun sollte</span></span></code></pre></div><p>Das ist besonders hilfreich für Einsteiger, da man leicht dazu neigt, &quot;Prototypen zu zeichnen, bevor man das Problem durchdacht hat&quot;.</p><h2 id="assignments" tabindex="-1">Assignments <a class="header-anchor" href="#assignments" aria-label="Permalink to “Assignments”">​</a></h2><p>Bitte bearbeiten Sie die folgenden Aufgaben basierend auf dem obigen Inhalt:</p><ol><li>Wählen Sie eine Produktidee, an der Sie kürzlich gedacht haben, und erstellen Sie einen Entwurf für die vier Schritte Discover, Define, Develop, Deliver</li><li>In der Define-Phase: Zwingen Sie sich, das Problem auf einen konkreten Satz zu verdichten</li><li>In der Develop-Phase: Listen Sie mindestens 3 verschiedene Lösungsansätze auf, anstatt nur den ersten Gedanken zu verfolgen</li><li>In der Deliver-Phase: Beschreiben Sie eine minimale validierbare Version, die Sie innerhalb einer Woche liefern können</li></ol><h2 id="weiterf-uuml-hrende-literatur" tabindex="-1">Weiterführende Literatur <a class="header-anchor" href="#weiterf-uuml-hrende-literatur" aria-label="Permalink to “Weiterf&amp;uuml;hrende Literatur”">​</a></h2><p>Dieser Artikel bezieht sich hauptsächlich auf die offiziellen Materialien des Design Council zum Double Diamond. Hier sind empfehlenswerte weiterführende Quellen:</p><ul><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/" target="_blank" rel="noreferrer">Design Council: The Double Diamond</a></li><li><a href="https://www.designcouncil.org.uk/our-work/skills-learning/tools-frameworks/framework-for-innovation-design-councils-evolved-double-diamond/" target="_blank" rel="noreferrer">Design Council: Framework for Innovation</a></li><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/history-of-the-double-diamond/" target="_blank" rel="noreferrer">Design Council: History of the Double Diamond</a></li></ul>`,171))])}}});export{g as __pageData,b as default};
